SELECT
    p.id AS problemId,
    p.problem_name AS problemName,
    p.difficulty,
    CASE
        WHEN upp.id IS NULL THEN 'UNATTEMPTED'
        ELSE upp.status
    END AS status
FROM problem p
LEFT JOIN user_problem_progress upp
    ON upp.problem_id = p.id
    AND upp.user_id = #{userId}
WHERE p.status = #{publishStatus}


    AND (
        p.problem_name LIKE CONCAT('%', #{dto.keyword}, '%')
        OR CAST(p.id AS CHAR) = #{dto.keyword}
    )



    AND p.difficulty >= #{dto.difficultyMin}



    AND p.difficulty <= #{dto.difficultyMax}



    AND EXISTS (
        SELECT 1
        FROM problem_tag pt_filter
        WHERE pt_filter.problem_id = p.id
          AND pt_filter.tag_id IN

            #{tagId}

    )





            AND upp.id IS NULL


            AND upp.status = #{dto.solveStatus}




ORDER BY p.id ASC

SELECT p.id AS problemId, p.problem_name AS problemName, p.difficulty, CASE WHEN upp.id IS NULL THEN 'UNATTEMPTED' ELSE upp.status END AS status, p.status AS problemStatus FROM problem p LEFT JOIN user_problem_progress upp ON upp.problem_id = p.id AND upp.user_id = #{userId} WHERE 1 = 1
AND ( p.problem_name LIKE CONCAT('%', #{dto.keyword}, '%') OR CAST(p.id AS CHAR) = #{dto.keyword} )
AND p.difficulty >= #{dto.difficultyMin}
AND p.difficulty <= #{dto.difficultyMax}
AND EXISTS ( SELECT 1 FROM problem_tag pt_filter WHERE pt_filter.problem_id = p.id AND pt_filter.tag_id IN
#{tagId}
)
AND upp.id IS NULL
AND upp.status = #{dto.solveStatus}
ORDER BY p.id ASC
